import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    filenames = input[2:2+n]
    to_delete_indices = list(map(int, input[2+n:]))
    to_delete = [filenames[i-1] for i in to_delete_indices]

    if len(set(len(f) for f in to_delete)) != 1:
        print("No")
        return

    pattern = []
    length = len(to_delete[0])
    for i in range(length):
        chars = set(f[i] for f in to_delete)
        if len(chars) == 1:
            pattern.append(next(iter(chars)))
        else:
            pattern.append('?')

    for f in filenames:
        if f not in to_delete and len(f) == length:
            matches = True
            for p, c in zip(pattern, f):
                if p != '?' and p != c:
                    matches = False
                    break
            if matches:
                print("No")
                return

    print("Yes")
    print("".join(pattern))

main()
